using System.Collections.Concurrent;using DadoRetail.Domain.Fiscalization;using DadoRetail.Domain.Payments;namespace DadoRetail.Api.Pilot;public sealed class PilotPaymentProvider:IPaymentProvider{private readonly ConcurrentDictionary<string,DateTime> created=new();public Task<PaymentProviderResult>CreateAsync(Guid paymentId,decimal amount,CancellationToken ct=default){var id=$"PILOT-{paymentId:N}";created[id]=DateTime.UtcNow;return Task.FromResult(new PaymentProviderResult(id,$"DADO-PILOT://pay/{id}?amount={amount:0.00}",DateTime.UtcNow.AddMinutes(5)));}public Task<PaymentProviderStatus>GetStatusAsync(string providerTransactionId,CancellationToken ct=default){if(!created.TryGetValue(providerTransactionId,out var at))return Task.FromResult(new PaymentProviderStatus(PaymentStatus.Failed));var status=DateTime.UtcNow-at>=TimeSpan.FromSeconds(3)?PaymentStatus.Paid:PaymentStatus.WaitingPayment;return Task.FromResult(new PaymentProviderStatus(status,status==PaymentStatus.Paid?"PILOT-APPROVED":null));}public Task CancelAsync(string providerTransactionId,CancellationToken ct=default){created.TryRemove(providerTransactionId,out _);return Task.CompletedTask;}}
public sealed class PilotFiscalizationProvider:IFiscalizationProvider{public Task<FiscalizationResult>FiscalizeAsync(Guid saleId,decimal amount,CancellationToken ct=default)=>Task.FromResult(new FiscalizationResult(true,$"PILOT-R-{saleId:N}",$"PILOT-{DateTime.UtcNow:yyyyMMddHHmmss}",null));public Task<FiscalizationResult>RefundAsync(Guid saleId,decimal amount,CancellationToken ct=default)=>Task.FromResult(new FiscalizationResult(true,$"PILOT-REF-{saleId:N}",$"PILOT-REF-{DateTime.UtcNow:yyyyMMddHHmmss}",null));}
